/// <summary>
/// init method extension
/// </summary>
void init()
{
    METVendParameters metVendParameters = METVendParameters::find();

    next init();

    // only show custom rebate fields for vendor charge codes
    markupTable_ds.object(fieldNum(MarkupTable, METIsOffRemittance)).visible(markupModule == MarkupModuleType::Vend);
    markupTable_ds.object(fieldNum(MarkupTable, METFollowTransactionTaxItemGroup)).visible(markupModule == MarkupModuleType::Vend);

    // enable is rebate code only if enable vendor rebates is Yes
    markupTable_ds.object(fieldNum(MarkupTable, METIsOffRemittance)).enabled(markupModule == MarkupModuleType::Vend && metVendParameters.VendorRebatesEnabled);
    markupTable_ds.object(fieldNum(MarkupTable, METFollowTransactionTaxItemGroup)).enabled(markupModule == MarkupModuleType::Vend && metVendParameters.VendorRebatesEnabled);
}

/// <summary>
/// Initializes the form based on the caller table.
/// </summary>
protected void initializeFromCallerTable()
{
    next initializeFromCallerTable();
    //<Bug 320423: PERF - Performance Issue with Submit purchase orders to workflow>
    switch (this.args().dataset())
    {
        case tableNum(CustParameters):
            markupModule    = MarkupModuleType::Cust;
            break;
    }
}
